# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student

PEOPLE = [
    Student("1", "Halloway", "Juno", "A"),
    Student("2", "Dunmere", "Piet", "A"),
    Student("3", "Arkwright", "Neve", "A")
]


class SeatRowsTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        self.assertEqual(
            seat_rows(PEOPLE, 2),
            ["Row 1: Arkwright, Neve | Dunmere, Piet", "Row 2: Halloway, Juno"]
        )

    def test_bad_seat_count_raises(self):
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seat_rows(PEOPLE, seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)


if __name__ == "__main__":
    unittest.main()
